38    boolean updateBoard(int position, String type) {
39
40        boolean returnValue;
41        // if a player selects position n, n-1 index should be updated
42        // if the position is not already filled, update the board
43        if (board.get(position - 1).equals(" ")) {
44            board.set(position - 1, type);
45
46
47            // increase the value of count by 1
48            count = count + 1;
49
50
51            returnValue = true;
52        }
53
54        // if the position is already filled, ask user to select another position
55        else {
56            System.out.println("Position already selected. Select another position.");
57            returnValue = false;
58        }
59        return returnValue;
60    }
