116class Game {
117
118    // create object of Board class
119    Board b1 = new Board();
120
121    // create object of Player class
122    Player player1 = new Player("X");
123    Player player2 = new Player("O");
124
125    // set currentPlayer as player1
126    Player currentPlayer = player1;
127
128    void play() {
129
130        // add elements to the board ArrayList
131        b1.addElements();
132        // using an infinite loop to run the game
133        // we will later add conditions to terminate the loop
134        String message = "enter the position (1 - 9):";
135        while (true) {
136
137            message = "enter the position (1 - 9):";
138            System.out.println(currentPlayer.name + " " + message);
139            Scanner input = new Scanner(System.in);
140            int position = input.nextInt();
141
142            // the updateBoard() method return true if
143            // the user selected position is not already filled
144            if (b1.updateBoard(position, currentPlayer.type)) {
145
146                b1.printBoard();
147
148                if (currentPlayer == player1) {
149                    currentPlayer = player2;
150                }
151
152                else {
153                    currentPlayer = player1;
154                }
155            }
156        }
157    }
158}
